-- prep-update-25: examiner scoring on a tablet, and report cards.
--
-- prep_score_sheets   what each black belt grading is scored on: up to seven categories (Patterns, Sparring, Breaking,
--                     Hands and kicks, Self defence, One step sparring, Weapons), each with the techniques from the
--                     AMA requirements, plus yes/no checks (flexibility, meditation, ...). Breaking only appears for
--                     Probationary Black Belt, 2nd Dan, 3rd Dan, 4th Dan and 5th Dan. Admins can edit the sheets.
-- prep_scores         one score out of 10 per examiner, per student, per category (with an optional note).
-- prep_score_notes    each examiner's strengths / to work on for a student, and their ticks for the checks.
-- prep_report_cards   the confirmed outcome (pass, distinction, retest, not yet) and summary for a student,
--                     with a private link the family can open once staff release it.
-- prep_score_summary  average per category across examiners.
-- prep_report_card(token)  what the family's report card page shows (released cards only).
--
-- Examiners (grading, instructor or admin role) enter and change only their own scores; grading staff confirm
-- outcomes and release report cards. Safe to run more than once.

create table if not exists public.prep_score_sheets (
  target_rank text primary key,
  from_rank   text,
  categories  jsonb not null default '[]'::jsonb,
  checks      text[] not null default '{}',
  updated_at  timestamptz not null default now()
);

create table if not exists public.prep_scores (
  cycle_id      uuid not null references public.prep_cycles(cycle_id) on delete cascade,
  student_id    text not null references public.prep_students(student_id) on delete cascade,
  examiner      text not null default public.prep_email(),
  examiner_name text,
  category      text not null,
  score         numeric(3,1) not null check (score >= 0 and score <= 10),
  note          text,
  updated_at    timestamptz not null default now(),
  primary key (cycle_id, student_id, examiner, category)
);

create table if not exists public.prep_score_notes (
  cycle_id      uuid not null references public.prep_cycles(cycle_id) on delete cascade,
  student_id    text not null references public.prep_students(student_id) on delete cascade,
  examiner      text not null default public.prep_email(),
  examiner_name text,
  strengths     text,
  work_on       text,
  checks        jsonb not null default '{}'::jsonb,
  updated_at    timestamptz not null default now(),
  primary key (cycle_id, student_id, examiner)
);

create table if not exists public.prep_report_cards (
  cycle_id     uuid not null references public.prep_cycles(cycle_id) on delete cascade,
  student_id   text not null references public.prep_students(student_id) on delete cascade,
  target_rank  text,
  outcome      text not null check (outcome in ('pass','distinction','retest','not_yet')),
  summary      text,
  token        text not null unique default public.prep_short_code(16),
  confirmed_by text default public.prep_email(),
  confirmed_at timestamptz not null default now(),
  released_at  timestamptz,
  released_by  text,
  primary key (cycle_id, student_id)
);

alter table public.prep_settings add column if not exists score_pass_min        numeric(3,1) not null default 5;
alter table public.prep_settings add column if not exists score_pass_avg        numeric(3,1) not null default 6;
alter table public.prep_settings add column if not exists score_distinction_avg numeric(3,1) not null default 8.5;

-- An examiner's own scores: the examiner is always the signed-in person, whatever the app sends
create or replace function public.prep_score_stamp() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if public.prep_email() is not null and not (public.prep_has_role('admin') and tg_op = 'UPDATE') then
    new.examiner := public.prep_email();
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists prep_scores_stamp on public.prep_scores;
create trigger prep_scores_stamp before insert or update on public.prep_scores for each row execute function public.prep_score_stamp();
drop trigger if exists prep_score_notes_stamp on public.prep_score_notes;
create trigger prep_score_notes_stamp before insert or update on public.prep_score_notes for each row execute function public.prep_score_stamp();

create or replace view public.prep_score_summary with (security_invoker = true) as
  select cycle_id, student_id, category, round(avg(score), 1) as average, count(*) as examiners,
         min(score) as lowest, max(score) as highest
    from public.prep_scores group by cycle_id, student_id, category;

-- ---- Row level security ----
alter table public.prep_score_sheets enable row level security;
alter table public.prep_scores       enable row level security;
alter table public.prep_score_notes  enable row level security;
alter table public.prep_report_cards enable row level security;
do $$
declare t text;
begin
  execute 'drop policy if exists "read" on public.prep_score_sheets';
  execute 'drop policy if exists "write" on public.prep_score_sheets';
  execute 'create policy "read" on public.prep_score_sheets for select to authenticated using (public.prep_can_view())';
  execute 'create policy "write" on public.prep_score_sheets for all to authenticated using (public.prep_has_role(''admin'')) with check (public.prep_has_role(''admin''))';
  foreach t in array array['prep_scores','prep_score_notes'] loop
    execute format('drop policy if exists "read" on public.%I', t);
    execute format('drop policy if exists "write" on public.%I', t);
    execute format('create policy "read" on public.%I for select to authenticated using (public.prep_can_view())', t);
    -- examiners write their own rows; admins can fix anyone's
    execute format('create policy "write" on public.%I for all to authenticated
      using (public.prep_has_role(''admin'') or (public.prep_has_role(''grading'',''instructor'') and examiner = public.prep_email()))
      with check (public.prep_has_role(''admin'') or (public.prep_has_role(''grading'',''instructor'') and examiner = public.prep_email()))', t);
  end loop;
  execute 'drop policy if exists "read" on public.prep_report_cards';
  execute 'drop policy if exists "write" on public.prep_report_cards';
  execute 'create policy "read" on public.prep_report_cards for select to authenticated using (public.prep_can_view())';
  execute 'create policy "write" on public.prep_report_cards for all to authenticated using (public.prep_has_role(''grading'')) with check (public.prep_has_role(''grading''))';
end $$;
grant select on public.prep_score_sheets, public.prep_scores, public.prep_score_notes, public.prep_report_cards, public.prep_score_summary to authenticated;
grant insert, update, delete on public.prep_score_sheets, public.prep_scores, public.prep_score_notes, public.prep_report_cards to authenticated;

-- ---- The family's report card (only once staff release it) ----
create or replace function public.prep_report_card(p_token text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare rc record; st record; sh record; cy record; out jsonb;
begin
  if p_token is null or length(p_token) < 12 then return null; end if;
  select * into rc from prep_report_cards where token = p_token and released_at is not null;
  if rc.token is null then return null; end if;
  select full_name, certificate_name, belt_rank into st from prep_students where student_id = rc.student_id;
  select name, grading_date into cy from prep_cycles where cycle_id = rc.cycle_id;
  select * into sh from prep_score_sheets where target_rank = rc.target_rank;
  select jsonb_build_object(
    'name', coalesce(nullif(btrim(st.certificate_name), ''), st.full_name),
    'target', rc.target_rank, 'from', coalesce(sh.from_rank, (select current_rank from prep_grading where cycle_id = rc.cycle_id and student_id = rc.student_id order by created_at desc limit 1)),
    'grading', cy.name, 'date', coalesce((select grading_date from prep_grading where cycle_id = rc.cycle_id and student_id = rc.student_id order by created_at desc limit 1), cy.grading_date),
    'outcome', rc.outcome, 'summary', rc.summary, 'released_at', rc.released_at,
    'categories', coalesce((
      select jsonb_agg(jsonb_build_object('key', c->>'key', 'label', c->>'label', 'items', c->'items',
                                          'score', (select round(avg(score), 1) from prep_scores s where s.cycle_id = rc.cycle_id and s.student_id = rc.student_id and s.category = c->>'key'),
                                          'notes', (select coalesce(jsonb_agg(s.note order by s.updated_at), '[]'::jsonb) from prep_scores s
                                                     where s.cycle_id = rc.cycle_id and s.student_id = rc.student_id and s.category = c->>'key' and coalesce(btrim(s.note), '') <> ''))
                       order by o)
        from jsonb_array_elements(sh.categories) with ordinality as x(c, o)), '[]'::jsonb),
    'checks', coalesce((
      select jsonb_agg(jsonb_build_object('label', ck, 'done',
               exists (select 1 from prep_score_notes n where n.cycle_id = rc.cycle_id and n.student_id = rc.student_id and (n.checks->>ck)::boolean)) order by o)
        from unnest(sh.checks) with ordinality as y(ck, o)), '[]'::jsonb),
    'comments', coalesce((
      select jsonb_agg(jsonb_build_object('by', case when coalesce(btrim(n.examiner_name), '') = '' or n.examiner_name like '%@%' then 'Examiner' else n.examiner_name end, 'strengths', n.strengths, 'work_on', n.work_on) order by n.updated_at)
        from prep_score_notes n where n.cycle_id = rc.cycle_id and n.student_id = rc.student_id
         and (coalesce(btrim(n.strengths), '') <> '' or coalesce(btrim(n.work_on), '') <> '')), '[]'::jsonb)
  ) into out;
  return out;
end $$;
revoke all on function public.prep_report_card(text) from public;
grant execute on function public.prep_report_card(text) to anon, authenticated;

